#include <fstream>
#include <iostream>
#include <string>

std::ifstream datei("daten.txt");
if (!datei) {                  // Öffnen fehlgeschlagen?
    std::cerr << "Datei fehlt!" << std::endl;
    return 1;
}

std::string zeile;
while (std::getline(datei, zeile)) {  // bis Dateiende
    std::cout << zeile << std::endl;
}

// Zahlen lesen:
