#include <fstream>
#include <iostream>

// Schreiben (überschreibt!)
std::ofstream datei("ausgabe.txt");
if (!datei) {
    std::cerr << "Kann nicht schreiben!" << std::endl;
    return 1;
}
datei << "Zeile 1" << std::endl;
datei << "Summe: " << (3 + 4) << std::endl;
datei.close();

// Anhängen:
std::ofstream log("log.txt", std::ios::app);
log << "Neuer Eintrag" << std::endl;
// RAII: log schließt sich am Ende des Blocks

